#include <stdio.h>
#include <stdlib.h>

static char *ibuf;
static size_t ipos, ilen;

static int readInt(void) {
    while (ipos < ilen && (ibuf[ipos] < '0' || ibuf[ipos] > '9') && ibuf[ipos] != '-') ipos++;
    int neg = 0;
    if (ipos < ilen && ibuf[ipos] == '-') { neg = 1; ipos++; }
    long x = 0;
    while (ipos < ilen && ibuf[ipos] >= '0' && ibuf[ipos] <= '9') {
        x = x * 10 + (ibuf[ipos] - '0');
        ipos++;
    }
    return neg ? (int)-x : (int)x;
}

int main(void) {
    /* ---- leitura rapida de toda a entrada ---- */
    size_t cap = 1 << 20;
    ibuf = (char *)malloc(cap);
    ilen = 0;
    for (;;) {
        if (ilen == cap) {
            cap <<= 1;
            ibuf = (char *)realloc(ibuf, cap);
        }
        size_t r = fread(ibuf + ilen, 1, cap - ilen, stdin);
        if (r == 0) break;
        ilen += r;
    }
    ipos = 0;

    int n = readInt();
    int *A = (int *)malloc((size_t)n * sizeof(int));
    for (int i = 0; i < n; i++) A[i] = readInt();

    int *ans = (int *)malloc((size_t)n * sizeof(int));
    const int INF = 0x3f3f3f3f;

    /*
     * Resposta para o degrau i: min sobre os degraus conhecidos j de (A_j + |i - j|).
     * Pois |h_i - h_j| <= |i - j| em qualquer reconstrução valida, e a construcao
     * h_k = min_j (A_j + |k - j|) e 1-Lipschitz, coincide com os valores conhecidos
     * e portanto e uma reconstrução valida que atinge esse limite para todo k.
     *
     * Calculamos em duas passadas:
     *   esquerda->direita: min_{j <= i} (A_j + (i - j)) = i + min_{j <= i} (A_j - j)
     *   direita->esquerda: min_{j >= i} (A_j + (j - i)) = min_{j >= i} (A_j + j) - i
     */

    int best = INF;
    for (int i = 0; i < n; i++) {
        if (A[i] != -1) {
            int v = A[i] - i;
            if (v < best) best = v;
        }
        ans[i] = (best == INF) ? INF : best + i;
    }

    best = INF;
    for (int i = n - 1; i >= 0; i--) {
        if (A[i] != -1) {
            int v = A[i] + i;
            if (v < best) best = v;
        }
        if (best != INF) {
            int c = best - i;
            if (c < ans[i]) ans[i] = c;
        }
    }

    /* ---- saída rapida ---- */
    size_t ocap = (size_t)n * 8 + 16;
    char *out = (char *)malloc(ocap);
    size_t olen = 0;
    for (int i = 0; i < n; i++) {
        int x = ans[i];
        char tmp[12];
        int t = 0;
        if (x == 0) tmp[t++] = '0';
        while (x > 0) { tmp[t++] = (char)('0' + x % 10); x /= 10; }
        while (t > 0) out[olen++] = tmp[--t];
        out[olen++] = (i == n - 1) ? '\n' : ' ';
    }
    fwrite(out, 1, olen, stdout);

    free(ibuf);
    free(A);
    free(ans);
    free(out);
    return 0;
}
